require_once dirname(__DIR__).'/src/bootstrap.php';$token=(string)($_GET['token']??$_POST['token']??'');$error=null;$stmt=db()->prepare('SELECT pr.*,u.role,u.status FROM password_resets pr JOIN users u ON u.id=pr.user_id WHERE pr.token_hash=? AND pr.used_at IS NULL AND pr.expires_at>NOW() LIMIT 1');$stmt->execute([token_hash($token)]);$reset=$stmt->fetch();if(request_method('POST')){Csrf::verify();if(!$reset)$error='This reset link is invalid or expired.';else{$p=$_POST['password']??'';$c=$_POST['password_confirmation']??'';if(strlen($p)<10)$error='Password must contain at least 10 characters.';elseif($p!==$c)$error='Passwords do not match.';else{$pdo=db();$pdo->beginTransaction();try{$pdo->prepare("UPDATE users SET password_hash=?,status=CASE WHEN status='pending_password' THEN 'active' ELSE status END WHERE id=?")->execute([password_hash($p,PASSWORD_DEFAULT),(int)$reset['user_id']]);$pdo->prepare('UPDATE password_resets SET used_at=NOW() WHERE id=?')->execute([(int)$reset['id']]);$pdo->commit();unset($_SESSION['dev_password_reset_url'],$_SESSION['dev_hospital_invite_url'],$_SESSION['dev_staff_invite_url']);audit('password_updated','user',(int)$reset['user_id']);flash('success','Password updated. You can now sign in.');redirect('login.php');}catch(Throwable $e){$pdo->rollBack();$error='Could not update the password.';}}}}
$pageTitle='Set Password';require dirname(__DIR__).'/src/templates/header.php';?>
<div class="form-card narrow"><div class="eyebrow">Account security</div><h1>Choose a new password</h1><?php if(!$reset):?><div class="error-list">This reset link is invalid or expired.</div><?php else:?><?php if($error):?><div class="error-list"><?=e($error)?></div><?php endif;?><form method="post"><?=Csrf::field()?><input type="hidden" name="token" value="<?=e($token)?>"><div class="field"><label>New password</label><input type="password" name="password" minlength="10" required></div><div class="field"><label>Confirm password</label><input type="password" name="password_confirmation" minlength="10" required></div><button class="btn">Save Password</button></form><?php endif;?></div>
